package com.harvestflow.registration.exception; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.Map;
@RestControllerAdvice(basePackages="com.harvestflow.registration") public class RegistrationExceptionHandler { @ExceptionHandler(RegistrationException.class) public ResponseEntity<Map<String,String>> registration(RegistrationException e){HttpStatus s=(e instanceof UsernameAlreadyExistsException||e instanceof MobileAlreadyRegisteredException)?HttpStatus.CONFLICT:HttpStatus.BAD_REQUEST;return ResponseEntity.status(s).body(Map.of("error","Registration error","message",e.getMessage()));} }
